// La prioridad la deciden las reglas acordadas, no la IA: así nunca se equivoca en lo básico.
const s = $('Solicitud nueva (Supabase)').item.json.body || {};

const enRango = ['Entre 20 y 60', 'Entre 60 y 120', 'Entre 120 y 500'].includes(s.comunidades);
const decide = ['Decido yo', 'Lo decido con mi socio o socia'].includes(s.decide);
const conPrisa = ['Cuanto antes', 'En los próximos tres meses'].includes(s.plazo);

let prioridad = 'media';
if (!enRango) prioridad = 'descartada';
else if (decide && conPrisa) prioridad = 'alta';

return { json: { ...s, prioridad } };

// A OpenAI solo van las respuestas del formulario: ni nombre, ni correo, ni teléfono, ni despacho.
const cfg = $('⚙️ Config').item.json;
const s = $json;

const respuestas = [
  `Comunidades que gestiona: ${s.comunidades || '(sin respuesta)'}`,
  `Tarea que más tiempo le come: ${s.mayor_reto || '(sin respuesta)'}`,
  `Tiempo al día en esa tarea: ${s.horas_tareas || '(sin respuesta)'}`,
  `Software del despacho: ${s.software || '(sin respuesta)'}`,
  `Qué ha intentado y qué pasó: «${(s.intentos || '(sin respuesta)').slice(0, 1500)}»`,
  `Para cuándo lo quiere: ${s.plazo || '(sin respuesta)'}`,
  `Quién decide la formación: ${s.decide || '(sin respuesta)'}`,
  `Prioridad ya calculada: ${s.prioridad}`,
].join('\n');

const cuerpo = {
  model: cfg.modelo,
  temperature: 0.2,
  messages: [
    { role: 'system', content: cfg.prompt_sistema },
    { role: 'user', content: respuestas },
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'preparacion_llamada',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        required: ['resumen', 'enfoque', 'preguntas', 'alertas'],
        properties: {
          resumen: { type: 'string' },
          enfoque: { type: 'string' },
          preguntas: { type: 'array', items: { type: 'string' } },
          alertas: { type: 'string' },
        },
      },
    },
  },
};

return { json: { cuerpo } };

// Si OpenAI falla, la solicitud no se pierde: sale como «sin_clasificar» y el aviso llega igual.
const s = $('Aplica reglas').item.json;
let ia = null;
try {
  const texto = $json.choices?.[0]?.message?.content;
  if (texto) ia = JSON.parse(texto);
} catch (e) { ia = null; }

const fallo = ia === null;
return { json: {
  ...s,
  prioridad: s.prioridad === 'descartada' ? 'descartada' : (fallo ? 'sin_clasificar' : s.prioridad),
  resumen_ia: fallo ? '' : ia.resumen,
  enfoque_ia: fallo ? '' : ia.enfoque,
  preguntas_ia: fallo ? [] : (ia.preguntas || []).slice(0, 3),
  alertas_ia: fallo
    ? 'La IA no respondió. Leed las respuestas directamente. Error: ' + JSON.stringify($json.error || $json).slice(0, 300)
    : ia.alertas,
}};

// Correo interno para el equipo. La prioridad va en el asunto para verla sin abrirlo.
const c = $('Lee respuesta').item.json;
const esc = v => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));

const etiqueta = { alta: '🟢 ALTA', media: '🟡 MEDIA', descartada: '⚪ DESCARTADA', sin_clasificar: '⚠️ SIN CLASIFICAR' }[c.prioridad];
const color = { alta: '#1f8a4c', media: '#b7791f', descartada: '#6b7280', sin_clasificar: '#c2410c' }[c.prioridad];

const fila = (k, v) => `<tr><td style="padding:6px 12px 6px 0;color:#6b7280;vertical-align:top;white-space:nowrap">${k}</td><td style="padding:6px 0">${esc(v) || '—'}</td></tr>`;

const preguntas = (c.preguntas_ia || []).map(p => `<li>${esc(p)}</li>`).join('');

const html = `<div style="font-family:'Segoe UI',Tahoma,sans-serif;max-width:640px;color:#1f2937;line-height:1.5">
  <p style="display:inline-block;padding:4px 10px;border-radius:4px;background:${color};color:#fff;font-weight:600;margin:0 0 12px">${etiqueta}</p>
  <h2 style="margin:0 0 4px">${esc(c.nombre)}${c.despacho ? ' · ' + esc(c.despacho) : ''}</h2>
  <p style="margin:0 0 16px">${esc(c.email)}${c.telefono ? ' · ' + esc(c.telefono) : ''}</p>
  ${c.resumen_ia ? `<p style="font-size:16px;margin:0 0 16px"><b>${esc(c.resumen_ia)}</b></p>` : ''}
  ${c.enfoque_ia ? `<h3 style="margin:16px 0 4px">Por dónde empezar la llamada</h3><p style="margin:0">${esc(c.enfoque_ia)}</p>` : ''}
  ${preguntas ? `<h3 style="margin:16px 0 4px">Preguntas para la llamada</h3><ul style="margin:0;padding-left:20px">${preguntas}</ul>` : ''}
  ${c.alertas_ia ? `<h3 style="margin:16px 0 4px;color:#c2410c">Ojo</h3><p style="margin:0">${esc(c.alertas_ia)}</p>` : ''}
  <h3 style="margin:20px 0 4px">Sus respuestas</h3>
  <table style="border-collapse:collapse;font-size:14px">
    ${fila('Comunidades', c.comunidades)}
    ${fila('Le come más tiempo', c.mayor_reto)}
    ${fila('Tiempo al día', c.horas_tareas)}
    ${fila('Software', c.software)}
    ${fila('Qué ha intentado', c.intentos)}
    ${fila('Plazo', c.plazo)}
    ${fila('Decide', c.decide)}
  </table>
  <p style="margin:20px 0 0;font-size:13px;color:#6b7280">La prioridad es una sugerencia. El estado de la solicitud lo cambiáis vosotros en Supabase (tabla solicitudes_despacho). Prometimos llamar en 24 horas a quien encaje.</p>
</div>`;

return { json: {
  asunto: `${etiqueta} · Diagnóstico · ${c.nombre} · ${c.comunidades || 'sin dato'}`,
  html,
}};
